\nprint('total signed volume (all tris):', total_signed, 'abs:', abs(total_signed))\\n\\n# exact vertex match components\\nvm = collections.defaultdict(list)\\nfor i, t in enumerate(tris):\\n    for v in t[:3]:\\n        vm[(v[0], v[1], v[2])].append(i)\\n\\nseen = set()\\ncomps = []\\nfor i in range(len(tris)):\\n    if i in seen:\\n        continue\\n    q = collections.deque([i]); seen.add(i); comp = []\\n    while q:\\n        c = q.popleft(); comp.append(c)\\n        for v in tris[c][:3]:\\n            for n in vm[(v[0], v[1], v[2])]:\\n                if n not in seen:\\n                    seen.add(n); q.append(n)\\n    comps.append(comp)\\n\\nprint('num components (exact vertex match):', len(comps))\\ncomp_info = []\\nfor comp in comps:\\n    vol = abs(signed_vol([tris[i] for i in comp]))\\n    ids = collections.Counter(tris[i][3] for i in comp)\\n    comp_info.append((vol, len(comp), ids, comp))\\ncomp_info.sort(key=lambda c: c[0], reverse=True)\\nprint('top 8 components by volume:')\\nfor vol, n, ids, _ in comp_info[:8]:\\n    print(f'  vol={vol:.6f} ntri={n} mat_ids={dict(ids)}')\\nprint('sum of component volumes:', sum(c[0] for c in comp_info))\\n\\n# largest component detail\\nlargest_vol, largest_n, largest_ids, comp_idx = comp_info[0]\\nprint('largest comp: ntri=', largest_n, 'unique mat ids:', se
